package com.loja.checkout.entrega;

import com.loja.checkout.dominio.Pedido;

import java.math.BigDecimal;

/**
 * Uma opcao de entrega. Para criar uma nova transportadora basta escrever uma classe
 * que implemente esta interface e anota-la com {@code @Component}: ela entra sozinha
 * no catalogo, sem mexer em mais nada.
 */
public interface ModalidadeEntrega {

    /** Codigo usado pelo site, ex.: "EXPRESSA". */
    String codigo();

    /** Prazo de entrega em dias. */
    int prazoDias(Pedido pedido);

    /** Diz se esta opcao atende o pedido (peso, regiao, etc.). */
    default boolean atende(Pedido pedido) {
        return true;
    }

    /** Valor do frete, ja arredondado para centavos. */
    BigDecimal calcularFrete(Pedido pedido);
}
EOF
cat > $B/entrega/FretePorPeso.java <<'EOF'
package com.loja.checkout.entrega;

import com.loja.checkout.dominio.Dinheiro;
import com.loja.checkout.dominio.Pedido;

import java.math.BigDecimal;

/** Base para as opcoes que cobram uma taxa fixa mais um valor por kg do pedido. */
public abstract class FretePorPeso implements ModalidadeEntrega {

    private final BigDecimal taxaFixa;
    private final BigDecimal valorPorKg;
    private final int prazoDias;

    protected FretePorPeso(String taxaFixa, String valorPorKg, int prazoDias) {
        this.taxaFixa = new BigDecimal(taxaFixa);
        this.valorPorKg = new BigDecimal(valorPorKg);
        this.prazoDias = prazoDias;
    }

    @Override
    public int prazoDias(Pedido pedido) {
        return prazoDias;
    }

    @Override
    public BigDecimal calcularFrete(Pedido pedido) {
        return Dinheiro.valor(taxaFixa.add(valorPorKg.multiply(pedido.pesoKg())));
    }
}
EOF
